  // Phạm vi đọc Nghiệm thu (khớp firestore.rules ntReadScopeOk): Phòng thuộc Khối mình theo teams.blockId,
  // hoặc Phòng chưa gắn blockId nhưng blockCode trùng mã Khối mình. Dùng để truy vấn từng Phòng (teamId ==).
  const ntKhoiScopeKey = useMemo(() => {
    if (!['gd_khoi', 'tro_ly_khoi', 'assistant'].includes(effectiveRoleKey)) return '';
    const ids = new Set(myBlocks.map((b: any) => b.id));
    const codes = new Set(myBlocks.map((b: any) => String(b.blockCode || '').trim()).filter(Boolean));
    const out = new Set<string>((teamsRaw as any[]).filter((t: any) => t?.id && (t.blockId ? ids.has(t.blockId) : codes.has(String(t.blockCode || '').trim()))).map((t: any) => t.id));
    if (effectiveRoleKey === 'gd_khoi') dualGdkTeamIds.forEach((id) => out.add(id));
    return [...out].sort().join(',');
  }, [effectiveRoleKey, myBlocks, teamsRaw, dualGdkTeamIds]);

  // Company-wide read-only viewers (rules: block.view / block_budget.view) that have no Khối of their own.
  // GĐKD: không xem toàn bộ Khối (chỉ Phòng mình) — fix/gdkd-scope.
  const isGlobalBlockViewer = (isMod || isGDDA) && canViewBlockBudget;

  // Blocks the user may operate on. Non-admins without a Khối get NONE (never "all blocks").
  const userAllowedBlocks = useMemo(() => {
    if (isAdmin || isSuperAdmin || isAccountant) return blocks;
    if (myBlocks.length > 0) return myBlocks;
    return isGlobalBlockViewer ? blocks : [];
  }, [isAdmin, isSuperAdmin, isAccountant, blocks, myBlocks, isGlobalBlockViewer]);

  const currentActiveBlock = useMemo(() => {
    const list = userAllowedBlocks;
    if (!list || list.length === 0) return null;

    // 1. If selectedBlockId is specified, look for exact ID match or code match or normalized match
    if (selectedBlockId) {
      const found = list.find(b => 
        b.id === selectedBlockId || 
        b.blockCode === selectedBlockId ||
        (b.id && b.id.toLowerCase() === selectedBlockId.toLowerCase()) ||
        (b.blockCode && b.blockCode.toLowerCase() === selectedBlockId.toLowerCase())
      );
      if (found) return found;

      // Check token match (e.g. if saved value is '79' or 'k79' or 'khoi79')
      const normSelected = normalizeBlockIdentifier(selectedBlockId);
      if (normSelected) {
        const foundNorm = list.find(b => {
          const nbCode = normalizeBlockIdentifier(b.blockCode);
          const nbName = normalizeBlockIdentifier(b.name);
          const nbId = normalizeBlockIdentifier(b.id);
          return nbCode === normSelected || nbName === normSelected || nbId === normSelected;
        });
        if (foundNorm) return foundNorm;
      }
    }

    // 2. If user is directly assigned to blocks (e.g. Khối 79 in myBlocks), prioritize myBlocks[0]!
    if (myBlocks.length > 0) {
      const myMatch = list.find(b => b.id === myBlocks[0].id || b.blockCode === myBlocks[0].blockCode);
      if (myMatch) return myMatch;
    }

    // 3. Check if userProfile has assignedBlock (e.g. 'Khối 79' or '79' or 'K79')
    const userBlockField = (userProfile?.assignedBlock || userProfile?.block || userProfile?.blockName || '').trim();
    if (userBlockField) {
      const normField = normalizeBlockIdentifier(userBlockField);
      if (normField) {
        const foundProfileBlock = list.find(b => {
          const nbCode = normalizeBlockIdentifier(b.blockCode);
          const nbName = normalizeBlockIdentifier(b.name);
          return nbCode === normField || nbName === normField;
        });
        if (foundProfileBlock) return foundProfileBlock;
      }
    }

    // 4. If no explicit block selected or assigned, prioritize any block with registered budgets
    const blockWithBudgets = list.find(b => blockBudgets.some(bb => isBlockMatch(bb, b)));
    if (blockWithBudgets) {
      return blockWithBudgets;
    }

    return list[0] || null;
  }, [userAllowedBlocks, selectedBlockId, myBlocks, userProfile, blockBudgets]);

