    if (isAdmin || isSuperAdmin || isAppOwnerEmail(user?.email)) return true;
    
    // Everyone else (GĐ Khối, Trợ lý Khối): ONLY records of blocks in their own Khối (rules: blockInMyKhoi).
    if (!myBlocks || myBlocks.length === 0) return false;
    return myBlocks.some(blk => b.blockId === blk.id || isBlockMatch(b, blk));
