  const guideItem = { value: 'huong-dan', label: 'Hướng dẫn', icon: BookOpen, color: 'text-emerald-600', activeBg: 'bg-indigo-600', activeText: 'text-white font-black', visible: true, desc: 'Quy trình thanh toán & thuế TKQC Meta' };
  const canGuide = vnGate || vnCan(vctx, 'vn.guide.view');
  const infoItem = { value: 'thong-tin-ho-tro', label: 'Thông tin Hỗ trợ', icon: Wallet, color: 'text-emerald-600', activeBg: 'bg-indigo-600', activeText: 'text-white font-black', visible: true, desc: 'Chính sách hỗ trợ MKT của mọi dự án (chỉ xem)' };
  const canInfo = !vnGate && vnCan(vctx, 'vn.support_info.view');
