  const [editingTeamCode, setEditingTeamCode] = useState('');
  const [editingTeamBlockId, setEditingTeamBlockId] = useState('none');
  const [adminTeamBlockFilter, setAdminTeamBlockFilter] = useState('all');
  const [adminTeamSort, setAdminTeamSort] = useState<'name-asc' | 'name-desc' | 'code-asc' | 'date-desc' | 'members-desc'>('name-asc');
  const [isImportingTeams, setIsImportingTeams] = useState(false);
  const [newTeamBlockId, setNewTeamBlockId] = useState('none');

  const teamMemberCounts = useMemo(() => {
    const map: Record<string, number> = {};
    allUsers.forEach(u => {
      if (u.teamId) {
        map[u.teamId] = (map[u.teamId] || 0) + 1;
      }
      if (u.teamName) {
        map[u.teamName] = (map[u.teamName] || 0) + 1;
      }
    });
    return map;
  }, [allUsers]);

  const filteredAdminTeams = useMemo(() => {
    return teams.filter(t => {
      const q = normVi(teamSearch);
      const matchesSearch = !q || 
        normVi(t.name).includes(q) || 
        normVi(t.teamCode).includes(q) ||
        normVi(t.blockCode).includes(q);
      
      const targetBlock = blocks.find(b => b.id === adminTeamBlockFilter || b.blockCode === adminTeamBlockFilter);
      const matchesBlock = adminTeamBlockFilter === 'all' || 
        (adminTeamBlockFilter === 'unassigned' && (!t.blockId || t.blockId === '' || t.blockId === 'unassigned')) ||
        (targetBlock ? isTeamInBlock(t, targetBlock, teams) : (t.blockId === adminTeamBlockFilter || t.blockCode === adminTeamBlockFilter));

      return matchesSearch && matchesBlock;
    }).sort((a, b) => {
      if (adminTeamSort === 'name-desc') return (b.name || '').localeCompare(a.name || '');
      if (adminTeamSort === 'code-asc') return (a.teamCode || '').localeCompare(b.teamCode || '');
      if (adminTeamSort === 'members-desc') {
        const countA = teamMemberCounts[a.id] || teamMemberCounts[a.name] || 0;
        const countB = teamMemberCounts[b.id] || teamMemberCounts[b.name] || 0;
        return countB - countA;
      }
      if (adminTeamSort === 'date-desc') {
        const timeA = a.createdAt?.toDate ? a.createdAt.toDate().getTime() : (a.createdAt ? new Date(a.createdAt).getTime() : 0);
        const timeB = b.createdAt?.toDate ? b.createdAt.toDate().getTime() : (b.createdAt ? new Date(b.createdAt).getTime() : 0);
        return timeB - timeA;
      }
      return (a.name || '').localeCompare(b.name || '');
    });
  }, [teams, teamSearch, adminTeamBlockFilter, adminTeamSort, teamMemberCounts]);

  // Project & Region sub-tab and dialog states
  const [projectSubTab, setProjectSubTab] = useState<'project-list' | 'project-regions' | 'project-ban-kd' | 'project-cdt'>('project-list');
  // Deep link /ban-kd opens Dự án · Ban KD on the Ban KD tab (routes map it to admin/projects).
  const routerLocation = useLocation();
  useEffect(() => {
    const clean = (routerLocation.pathname || '/').replace(/\/+$/, '') || '/';
    if (clean === '/ban-kd') setProjectSubTab('project-ban-kd');
  }, [routerLocation.pathname]);
  const [newProjectBanKdId, setNewProjectBanKdId] = useState('');
  const [editingProjectBanKdId, setEditingProjectBanKdId] = useState('');
  const [adminProjectBanKdFilter, setAdminProjectBanKdFilter] = useState('all');
  const [selectedBanKdForBulk, setSelectedBanKdForBulk] = useState('');
  const [isBulkUpdateBanKdDialogOpen, setIsBulkUpdateBanKdDialogOpen] = useState(false);
  const [adminBlockBudgetFilterBanKd, setAdminBlockBudgetFilterBanKd] = useState('all');
  const [isAddRegionDialogOpen, setIsAddRegionDialogOpen] = useState(false);

  // Region management states
  const [newRegionName, setNewRegionName] = useState('');
  const [editingRegionId, setEditingRegionId] = useState<string | null>(null);
  const [editingRegionName, setEditingRegionName] = useState('');
  const [regionSearch, setRegionSearch] = useState('');
  const [regionSort, setRegionSort] = useState<{ key: string, direction: 'asc' | 'desc' }>({ key: 'name', direction: 'asc' });
  const [isDeleteRegionDialogOpen, setIsDeleteRegionDialogOpen] = useState(false);
