  // Waits for the profile (userRole) so a Trưởng ban never fires a denied full-collection list.
  const banKdScopeKey = !user || !userRole ? '' : ((isTruongBanKd || isPhoBanKd) ? `leader:${user.uid}:${normalizeEmail(user.email)}` : 'all');
  useEffect(() => {
    if (!user || !banKdScopeKey) return;
    if (banKdScopeKey === 'all') {
      const qBanKd = query(collection(db, 'ban_kd'), orderBy('name', 'asc'));
      return onSnapshot(qBanKd, (snapshot) => {
        setBanKdList(snapshot.docs.map(d => ({ id: d.id, ...d.data() } as BanKd)));
        setScopeDataLoaded(prev => ({ ...prev, banKd: true }));
      }, (error) => { setScopeDataLoaded(prev => ({ ...prev, banKd: true })); handleFirestoreError(error, OperationType.LIST, 'ban_kd'); });
    }
    const email = normalizeEmail(user.email);
    const queries = [
      query(collection(db, 'ban_kd'), where('leaderUid', '==', user.uid)),
      query(collection(db, 'ban_kd'), where('leaderId', '==', user.uid)),
      ...(email ? [query(collection(db, 'ban_kd'), where('leaderEmail', '==', email))] : []),
      query(collection(db, 'ban_kd'), where('deputyUids', 'array-contains', user.uid)),
    ];
    const parts: Array<Map<string, BanKd> | null> = queries.map(() => null);
    const publish = () => {
      if (parts.some(p => p === null)) return;
      const merged = new Map<string, BanKd>();
      parts.forEach(p => p!.forEach((v, k) => merged.set(k, v)));
      setBanKdList(Array.from(merged.values()).sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''))));
      setScopeDataLoaded(prev => ({ ...prev, banKd: true }));
    };
    const unsubs = queries.map((q, i) => onSnapshot(q, (snapshot) => {
      parts[i] = new Map(snapshot.docs.map(d => [d.id, { id: d.id, ...d.data() } as BanKd]));
      publish();
    }, (error) => {
      console.warn('ban_kd (Trưởng ban) listener error:', error);
      parts[i] = new Map();
      publish();
    }));
    return () => unsubs.forEach(u => u());
  }, [user?.uid, banKdScopeKey]);

