  const handleUpdateUserRole = async (userId: string, newRole: string, assignedProjects: string[] = []) => {
    if (!(isAdmin || isSuperAdmin)) {
      toast.error("Chỉ Admin / Super Admin được đổi vai trò hoặc phạm vi (dự án, Khối, Ban KD) của tài khoản.");
      return;
    }
    try {
      const u = allUsers.find((x: any) => x.id === userId);
      const leavingTb = (u?.role || '') === 'truong_ban_kd' && newRole !== 'truong_ban_kd';
      const leavingPb = (u?.role || '') === 'pho_ban_kd' && newRole !== 'pho_ban_kd';
      const clear = leavingTb && u ? planClearLeadership(u, banKdList as any[]) : null;
      const clearDep = leavingPb && u ? planClearDeputyship(u, banKdList as any[]) : null;
      const batch = writeBatch(db);
      const userPatch: any = {
        role: newRole,
        assignedProjects,
        updatedAt: serverTimestamp()
      };
      if (clearDep?.userAssigned) {
        userPatch.assignedBanKd = clearDep.userAssigned.assignedBanKd;
        userPatch.assignedBanKds = clearDep.userAssigned.assignedBanKds;
      }
      batch.update(doc(db, 'users', userId), userPatch);
      clear?.banUpdates.forEach((b) => batch.update(doc(db, 'ban_kd', b.id), { ...b.data, updatedAt: serverTimestamp() }));
      clearDep?.banUpdates.forEach((b) => batch.update(doc(db, 'ban_kd', b.id), { ...b.data, updatedAt: serverTimestamp() }));
      await batch.commit();
      await logAction('UPDATE_USER_ROLE', 'users', userId, {
        role: newRole, assignedProjects,
        clearedLeaderBans: clear?.clearedBanIds || [],
        clearedDeputyBans: clearDep?.clearedBanIds || [],
      });
      const bits: string[] = [];
      if (clear?.clearedBanIds?.length) bits.push(`gỡ Trưởng Ban ở ${clear.clearedBanIds.length} Ban`);
      if (clearDep?.clearedBanIds?.length) bits.push(`gỡ Phó Ban ở ${clearDep.clearedBanIds.length} Ban`);
      toast.success(bits.length ? `Đã cập nhật quyền và ${bits.join('; ')}` : 'Đã cập nhật quyền người dùng');
    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, 'users');
    }
  };

