            <Card className="border-none shadow-xl shadow-slate-200/50 overflow-hidden bg-[var(--mh-surface)]/80 backdrop-blur-md rounded-[32px]">
              <div className="p-8 border-b border-[var(--mh-border)] flex items-center justify-between">
                <div>
                  <CardTitle className="text-xl font-black text-[var(--mh-text)] tracking-tight">Chi tiết Hiệu quả Kinh doanh</CardTitle>
                  <p className="text-[var(--mh-text-2)] text-[10px] font-medium uppercase tracking-widest mt-1">Sắp xếp theo doanh số thực nhận</p>
                </div>
                <div className="flex p-0.5 bg-[var(--mh-surface-2)] rounded-xl border border-[var(--mh-border)]">
                  <Button 
                    variant={efficiencyGroupType === 'team' ? 'secondary' : 'ghost'} 
                    size="sm" 
                    onClick={() => setEfficiencyGroupType('team')}
                    className={`h-8 text-[10px] px-4 rounded-lg transition-all ${efficiencyGroupType === 'team' ? 'bg-[var(--mh-surface)] shadow-sm text-indigo-600 font-black' : 'text-[var(--mh-text-2)] font-bold'}`}
                  >
                    Đội ngũ
                  </Button>
                  <Button 
                    variant={efficiencyGroupType === 'project' ? 'secondary' : 'ghost'} 
                    size="sm" 
                    onClick={() => setEfficiencyGroupType('project')}
                    className={`h-8 text-[10px] px-4 rounded-lg transition-all ${efficiencyGroupType === 'project' ? 'bg-[var(--mh-surface)] shadow-sm text-indigo-600 font-black' : 'text-[var(--mh-text-2)] font-bold'}`}
                  >
                    Dự án
                  </Button>
                </div>
              </div>
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader className="bg-[var(--mh-surface-2)]/80">
                    <TableRow className="hover:bg-transparent border-none">
                      <TableHead className="text-[10px] font-black uppercase tracking-widest text-[var(--mh-text-3)] pl-8 h-12 w-16">STT</TableHead>
                      <TableHead 
                        className="text-[10px] font-black uppercase tracking-widest text-[var(--mh-text-3)] h-12 cursor-pointer hover:bg-[var(--mh-surface-2)] transition-colors"
                        onClick={() => setEfficiencyTableSort(prev => ({ key: 'name', direction: prev.key === 'name' && prev.direction === 'asc' ? 'desc' : 'asc' }))}
                      >
                        <div className="flex items-center gap-1">
                          Đối tượng <ArrowUpDown className="w-3 h-3 text-[var(--mh-text-3)]" />
                        </div>
                      </TableHead>
                      <TableHead 
                        className="text-[10px] font-black uppercase tracking-widest text-[var(--mh-text-3)] text-right h-12 cursor-pointer hover:bg-[var(--mh-surface-2)] transition-colors"
                        onClick={() => setEfficiencyTableSort(prev => ({ key: 'budget', direction: prev.key === 'budget' && prev.direction === 'asc' ? 'desc' : 'asc' }))}
                      >
                        <div className="flex items-center justify-end gap-1">
                          Ngân sách <ArrowUpDown className="w-3 h-3 text-[var(--mh-text-3)]" />
                        </div>
                      </TableHead>
                      <TableHead 
                        className="text-[10px] font-black uppercase tracking-widest text-[var(--mh-text-3)] text-right h-12 cursor-pointer hover:bg-[var(--mh-surface-2)] transition-colors"
                        onClick={() => setEfficiencyTableSort(prev => ({ key: 'cost', direction: prev.key === 'cost' && prev.direction === 'asc' ? 'desc' : 'asc' }))}
                      >
                        <div className="flex items-center justify-end gap-1">
                          Thực chi <ArrowUpDown className="w-3 h-3 text-[var(--mh-text-3)]" />
                        </div>
                      </TableHead>
                      <TableHead 
                        className="text-[10px] font-black uppercase tracking-widest text-[var(--mh-text-3)] text-center h-12 cursor-pointer hover:bg-[var(--mh-surface-2)] transition-colors"
                        onClick={() => setEfficiencyTableSort(prev => ({ key: 'sales', direction: prev.key === 'sales' && prev.direction === 'asc' ? 'desc' : 'asc' }))}
                      >
                        <div className="flex items-center justify-center gap-1">
                          Căn bán <ArrowUpDown className="w-3 h-3 text-[var(--mh-text-3)]" />
                        </div>
                      </TableHead>
                      <TableHead 
                        className="text-[10px] font-black uppercase tracking-widest text-[var(--mh-text-3)] text-right h-12 cursor-pointer hover:bg-[var(--mh-surface-2)] transition-colors"
                        onClick={() => setEfficiencyTableSort(prev => ({ key: 'revenue', direction: prev.key === 'revenue' && prev.direction === 'asc' ? 'desc' : 'asc' }))}
                      >
                        <div className="flex items-center justify-end gap-1">
                          Doanh số <ArrowUpDown className="w-3 h-3 text-[var(--mh-text-3)]" />
                        </div>
                      </TableHead>
                      <TableHead 
                        className="text-[10px] font-black uppercase tracking-widest text-[var(--mh-text-3)] text-right pr-8 h-12 cursor-pointer hover:bg-[var(--mh-surface-2)] transition-colors"
                        onClick={() => setEfficiencyTableSort(prev => ({ key: 'roi', direction: prev.key === 'roi' && prev.direction === 'asc' ? 'desc' : 'asc' }))}
                      >
                        <div className="flex items-center justify-end gap-1">
                          ROI <ArrowUpDown className="w-3 h-3 text-[var(--mh-text-3)]" />
                        </div>
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {(() => {
                      const sortedData = [...efficiencyChartData].sort((a, b) => {
                        const factor = efficiencyTableSort.direction === 'asc' ? 1 : -1;
                        if (efficiencyTableSort.key === 'revenue') return (a.revenue - b.revenue) * factor;
                        if (efficiencyTableSort.key === 'cost') return (a.cost - b.cost) * factor;
                        if (efficiencyTableSort.key === 'budget') return (a.budget - b.budget) * factor;
                        if (efficiencyTableSort.key === 'name') return (a.name || '').localeCompare(b.name || '') * factor;
                        if (efficiencyTableSort.key === 'sales') return (a.sales - b.sales) * factor;
                        if (efficiencyTableSort.key === 'roi') {
                          const roiA = a.cost > 0 ? a.revenue / a.cost : 0;
                          const roiB = b.cost > 0 ? b.revenue / b.cost : 0;
                          return (roiA - roiB) * factor;
                        }
                        return 0;
                      });
                      return sortedData.slice(0, 10).map((item, idx) => {
                        const roi = item.cost > 0 && item.revenue > 0 ? (item.revenue / item.cost).toFixed(2) : null;
                        const isOverBudget = item.cost > item.budget;
                        return (
                          <TableRow key={idx} className="group hover:bg-indigo-50/20 transition-colors border-b-slate-100/50 h-20">
                            <TableCell className="pl-8 font-bold text-[var(--mh-text-3)] text-xs">{idx + 1}</TableCell>
                            <TableCell>
                              <div className="flex items-center gap-4">
                                <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-sm shadow-sm ${item.revenue > 0 ? 'bg-indigo-100 text-indigo-600' : 'bg-[var(--mh-surface-2)] text-[var(--mh-text-3)]'}`}>
                                  {item.name.charAt(0)}
                                </div>
                                <div>
                                  <p className="font-black text-[var(--mh-text)] uppercase tracking-tight text-sm">{item.name}</p>
                                  <p className="text-[10px] text-[var(--mh-text-3)] font-medium lowercase italic">
                                    {efficiencyGroupType === 'project' ? `${item.details.length} teams tham gia` : `${item.details.length} dự án triển khai`}
                                  </p>
                                </div>
                              </div>
                            </TableCell>
                            <TableCell className="text-right font-bold text-[var(--mh-text-3)] font-mono text-xs">{formatCurrency(item.budget)}</TableCell>
                            <TableCell className={`text-right font-black font-mono text-xs ${isOverBudget ? 'text-rose-500' : 'text-[var(--mh-text)] opacity-70'}`}>
                              {formatCurrency(item.cost)}
                            </TableCell>
                            <TableCell className="text-center">
                              <Badge variant="secondary" className="bg-emerald-100 text-emerald-700 font-black border-none px-3 h-6 text-[10px] rounded-lg">
                                {item.sales} căn
                              </Badge>
                            </TableCell>
                            <TableCell className="text-right font-black text-indigo-600 font-mono text-sm">{formatCurrency(item.revenue)}</TableCell>
                            <TableCell className="text-right pr-8">
                              <div className="flex flex-col items-end">
                                <span className="text-sm font-black text-indigo-700 italic tabular-nums">{roi ? `${roi}x` : '—'}</span>
                                {roi && parseFloat(roi) >= 5 && <span className="text-[8px] bg-amber-100 text-amber-700 px-1 rounded font-black uppercase">Hiệu quả cao</span>}
                              </div>
                            </TableCell>
                          </TableRow>
                        );
                      });
                    })()}
                  </TableBody>
                </Table>
              </div>
              {efficiencyChartData.length > 10 && (
                <div className="p-6 bg-[var(--mh-surface-2)]/50 border-t border-[var(--mh-border)] flex justify-center">
                  <Button variant="ghost" size="sm" onClick={() => setActiveTab('admin')} className="text-indigo-600 font-black text-[10px] uppercase tracking-widest gap-2">
                    Xem toàn bộ {efficiencyChartData.length} đơn vị tại trang báo cáo <ArrowRight className="w-3 h-3" />
                  </Button>
                </div>
              )}
            </Card>

            {/* Mục: Ngân Sách Marketing Của Từng Khối tại Trung Tâm Điều Hành */}
