                                                if (!editingBlockTeamName.trim()) {
                                                  toast.error("Tên phòng kinh doanh không được để trống!");
                                                  return;
                                                }
                                                if (!editingBlockTeamCode.trim()) {
                                                  toast.error("Mã phòng không được để trống!");
                                                  return;
                                                }
                                                try {
                                                  await updateDoc(doc(db, 'teams', team.id), {
                                                    name: editingBlockTeamName.trim(),
                                                    teamCode: editingBlockTeamCode.trim().toUpperCase(),
                                                    ...(!team.blockId || team.blockId === 'unassigned' ? { blockId: currentActiveBlock?.id, blockCode: currentActiveBlock?.blockCode || currentActiveBlock?.id } : {}),
                                                    updatedAt: serverTimestamp()
                                                  });
                                                  await logAction('UPDATE', 'teams', team.id, { name: editingBlockTeamName, teamCode: editingBlockTeamCode });
                                                  toast.success("Đã lưu cập nhật!");
                                                  setEditingBlockTeamId(null);
                                                } catch (err) {
                                                  handleFirestoreError(err, OperationType.UPDATE, 'teams');
                                                }
